    public static ForkGasSchedule? GetFork(string fork) =>
        AllForks.FirstOrDefault(f => string.Equals(f.Fork, fork, System.StringComparison.OrdinalIgnoreCase));

    public static ulong? Get(string fork, string name)
    {
        var schedule = GetFork(fork);
        if (schedule is null) return null;
        return schedule.Constants.TryGetValue(name, out var c) ? c.Value : null;
    }
